1	import { useState, useEffect, useRef } from "react";
2	import { motion, AnimatePresence } from "framer-motion";
3	import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
4	import { useLocation } from "wouter";
5	import { QRCodeDisplay } from "@/components/qr-code-display";
6	import { apiRequest } from "@/lib/queryClient";
7	import { sseClient } from "@/lib/sse-client";
8	import { useToast } from "@/hooks/use-toast";
9	import { useDeviceStatusMonitoring, useSSEConnectionMonitoring } from "@/components/notification-system";
10	import { getCurrentMerchantId } from "@/lib/auth";
11	import { Loader2, CheckCircle, XCircle, Waves, X } from "lucide-react";
12	import { canTapToPay } from "@/lib/native";
13	import RetailTerminalView, {
14	  type RetailCreateOptions,
15	  type RetailRefundIntent,
16	  type RetailSaleDraft,
17	  type RetailShareIntent,
18	  type RetailTerminalState,
19	} from "@/features/terminal/retail/RetailTerminalView";
20	
21	const BRAND = "#00DFC8";
22	
23	const RETAIL_QR_SVG = `<svg xmlns="http://www.w3.org/2000/svg" width="300" height="300" viewBox="0 0 60 60" fill="none"><rect width="60" height="60" fill="#040D6D"/><path d="M6 14V8a2 2 0 012-2h6" stroke="#58ABFF" stroke-width="3" stroke-linecap="round"/><path d="M54 14V8a2 2 0 00-2-2h-6" stroke="#58ABFF" stroke-width="3" stroke-linecap="round"/><path d="M6 46v6a2 2 0 002 2h6" stroke="#58ABFF" stroke-width="3" stroke-linecap="round"/><path d="M54 46v6a2 2 0 01-2 2h-6" stroke="#58ABFF" stroke-width="3" stroke-linecap="round"/><rect x="18" y="18" width="9" height="9" rx="1.5" fill="#58ABFF"/><rect x="33" y="18" width="9" height="9" rx="1.5" fill="#58ABFF"/><rect x="18" y="33" width="9" height="9" rx="1.5" fill="#58ABFF"/><rect x="33" y="33" width="3" height="3" fill="#58ABFF"/><rect x="38" y="33" width="3" height="3" fill="#58ABFF"/><rect x="33" y="38" width="3" height="3" fill="#58ABFF"/><rect x="38" y="38" width="3" height="3" fill="#58ABFF"/></svg>`;
24	
25	async function handleBrowserShare(intent: RetailShareIntent): Promise<void> {
26	  if (intent.channel === "copy") {
27	    await navigator.clipboard?.writeText(intent.url).catch(() => {});
28	    return;
29	  }
30	
31	  if (intent.channel === "download-qr") {
32	    const blob = new Blob([RETAIL_QR_SVG], { type: "image/svg+xml" });
33	    const url = URL.createObjectURL(blob);
34	    const anchor = document.createElement("a");
35	    anchor.href = url;
36	    anchor.download = `${intent.kind}-qr.svg`;
37	    anchor.click();
38	    setTimeout(() => URL.revokeObjectURL(url), 1000);
39	    return;
40	  }
41	
42	  const subject = intent.kind === "receipt"
43	    ? "Your Receipt"
44	    : `Payment Request — $${(intent.amountCents / 100).toFixed(2)}`;
45	  const body = intent.kind === "receipt"
46	    ? `Your receipt: ${intent.url}`
47	    : `Pay here: ${intent.url}`;
48	
49	  if (intent.channel === "email") {
50	    window.open(`mailto:?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`);
51	    return;
52	  }
53	
54	  const isAppleDevice = /Mac|iPhone|iPad/.test(navigator.userAgent);
55	  window.open(`sms:${isAppleDevice ? "&" : "?"}body=${encodeURIComponent(body)}`);
56	}
57	
58	export default function MerchantTerminalMobile() {
59	  const [selectedStoneId, setSelectedStoneId] = useState<number | null>(null);
60	  const [successNotif, setSuccessNotif] = useState<{ id: string; message: string; amount?: string } | null>(null);
61	  const prevTransactionStatusRef = useRef<string | null>(null);
62	
63	  const [tapToPayStatus, setTapToPayStatus] = useState<"idle" | "waiting" | "processing" | "completed" | "failed">("idle");
64	  const [tapToPayApproved, setTapToPayApproved] = useState<boolean | null>(null);
65	  const [showTapToPayOverlay, setShowTapToPayOverlay] = useState(false);
66	
67	  const audioCtxRef = useRef<AudioContext | null>(null);
68	
69	  useEffect(() => {
70	    const AudioCtx: typeof AudioContext =
71	      window.AudioContext ||
72	      (window as Window & { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
73	    if (!AudioCtx) return;
74	    const ctx = new AudioCtx();
75	    audioCtxRef.current = ctx;
76	    const unlock = () => { if (ctx.state === "suspended") ctx.resume(); };
77	    window.addEventListener("click", unlock, { once: false });
78	    window.addEventListener("touchstart", unlock, { once: false });
79	    window.addEventListener("keydown", unlock, { once: false });
80	    return () => {
81	      window.removeEventListener("click", unlock);
82	      window.removeEventListener("touchstart", unlock);
83	      window.removeEventListener("keydown", unlock);
84	      ctx.close();
85	    };
86	  }, []);
87	
88	  const playSuccessChime = async () => {
89	    try {
90	      const ctx = audioCtxRef.current;
91	      if (!ctx) return;
92	      if (ctx.state === "suspended") await ctx.resume();
93	      const playTone = (freq: number, startTime: number, duration: number, gain: number) => {
94	        const osc = ctx.createOscillator();
95	        const gainNode = ctx.createGain();
96	        osc.connect(gainNode);
97	        gainNode.connect(ctx.destination);
98	        osc.type = "sine";
99	        osc.frequency.setValueAtTime(freq, startTime);
100	        gainNode.gain.setValueAtTime(0, startTime);
101	        gainNode.gain.linearRampToValueAtTime(gain, startTime + 0.018);
102	        gainNode.gain.exponentialRampToValueAtTime(0.001, startTime + duration);
103	        osc.start(startTime);
104	        osc.stop(startTime + duration);
105	      };
106	      const t = ctx.currentTime;
107	      playTone(523.25, t,        0.22, 0.28);
108	      playTone(659.25, t + 0.09, 0.22, 0.30);
109	      playTone(783.99, t + 0.18, 0.22, 0.30);
110	      playTone(1046.5, t + 0.27, 0.55, 0.36);
111	    } catch (e) { console.warn("Chime failed:", e); }
112	  };
113	
114	  const queryClient = useQueryClient();
115	  const { toast } = useToast();
116	  const [, setLocation] = useLocation();
117	  const merchantId = getCurrentMerchantId();
118	
119	  const { data: merchant } = useQuery({
120	    queryKey: ["/api/merchants", merchantId, "profile"],
121	    queryFn: async () => {
122	      const r = await fetch(`/api/merchants/${merchantId}/profile`, {
123	        headers: { Authorization: `Bearer ${localStorage.getItem("authToken")}` },
124	      });
125	      if (!r.ok) throw new Error("Failed to fetch merchant");
126	      return r.json();
127	    },
128	    enabled: !!merchantId,
129	  });
130	
131	  const { data: activeTransaction } = useQuery({
132	    queryKey: ["/api/merchants", merchantId, "active-transaction"],
133	    queryFn: async () => {
134	      const r = await fetch(`/api/merchants/${merchantId}/active-transaction`);
135	      if (!r.ok) throw new Error("Failed to fetch active transaction");
136	      return r.json();
137	    },
138	    // SSE keeps this cache live via queryClient.setQueryData — no polling needed.
139	    // A 30 s fallback refetch guards against SSE gaps (disconnect, reconnect lag).
140	    refetchInterval: 30000,
141	    enabled: !!merchantId,
142	  });
143	
144	  const { data: taptStones = [] } = useQuery({
145	    queryKey: ["/api/merchants", merchantId, "tapt-stones"],
146	    queryFn: async () => {
147	      const authToken = localStorage.getItem("authToken");
148	      const r = await fetch(`/api/merchants/${merchantId}/tapt-stones`, {
149	        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
150	      });
151	      if (!r.ok) throw new Error("Failed to fetch tapt stones");
152	      return r.json();
153	    },
154	    enabled: !!merchantId,
155	  });
156	
157	  const { data: allTransactions = [] } = useQuery({
158	    queryKey: ["/api/merchants", merchantId, "transactions"],
159	    queryFn: async () => {
160	      const authToken = localStorage.getItem("authToken");
161	      const r = await fetch(`/api/merchants/${merchantId}/transactions`, {
162	        headers: authToken ? { Authorization: `Bearer ${authToken}` } : {},
163	      });
164	      if (!r.ok) throw new Error("Failed to fetch transactions");
165	      return r.json();
166	    },
167	    refetchInterval: 5000,
168	    enabled: !!merchantId,
169	  });
170	
171	  useEffect(() => {
172	    if ((taptStones as any[]).length > 0 && selectedStoneId === null) {
173	      setSelectedStoneId((taptStones as any[])[0].id);
174	    }
175	  }, [taptStones, selectedStoneId]);
176	
177	  useEffect(() => {
178	    if (!merchantId) return;
179	    const token = localStorage.getItem("authToken");
180	    if (!token) return;
181	    sseClient.connectMerchant(merchantId, token);
182	    sseClient.subscribe("transaction_updated", (message) => {
183	      const tx = message.transaction ?? null;
184	      queryClient.setQueryData(["/api/merchants", merchantId, "active-transaction"], tx);
185	      // Keep allTransactions cache in sync for all updates so split progress,
186	      // status changes, and completedSplits increments appear immediately.
187	      if (tx) {
188	        queryClient.setQueryData<any[]>(
189	          ["/api/merchants", merchantId, "transactions"],
190	          (prev: any[] = []) => {
191	            const exists = prev.some((t: any) => t.id === tx.id);
192	            return exists
193	              ? prev.map((t: any) => (t.id === tx.id ? tx : t))
194	              : [tx, ...prev];
195	          }
196	        );
197	      }
198	    });
199	    return () => { sseClient.disconnect(); };
200	  }, [merchantId, queryClient]);
201	
202	  useDeviceStatusMonitoring();
203	  useSSEConnectionMonitoring(merchantId ?? 0);
204	
205	  useEffect(() => {
206	    const prev = prevTransactionStatusRef.current;
207	    const status = activeTransaction?.status ?? null;
208	    if (status === "completed" && prev && prev !== "completed") {
209	      playSuccessChime();
210	      const amount = activeTransaction?.price
211	        ? parseFloat(activeTransaction.price).toFixed(2)
212	        : undefined;
213	      setSuccessNotif({ id: `success-${Date.now()}`, message: "Payment Received", amount });
214	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
215	    }
216	    prevTransactionStatusRef.current = status;
217	  }, [activeTransaction?.status]);
218	
219	  const createTransactionMutation = useMutation({
220	    mutationFn: async (data: { itemName: string; price: string; selectedStoneId?: number; splitEnabled?: boolean }) => {
221	      const r = await apiRequest("POST", "/api/transactions", {
222	        merchantId,
223	        itemName: data.itemName,
224	        price: data.price,
225	        status: "pending",
226	        selectedStoneId: data.selectedStoneId,
227	        splitEnabled: data.splitEnabled ?? false,
228	      });
229	      return r.json();
230	    },
231	    onSuccess: () => {
232	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
233	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "transactions"] });
234	    },
235	    onError: () => {
236	      toast({ title: "Error", description: "Failed to create transaction", variant: "destructive" });
237	    },
