239	
240	  const createStoneMutation = useMutation({
241	    mutationFn: async () => {
242	      const stoneNumber = ((taptStones as any[])?.length || 0) + 1;
243	      const r = await apiRequest("POST", `/api/merchants/${merchantId}/tapt-stones`, {
244	        name: `Stone ${stoneNumber}`,
