308	        bridgeResult = { approved: true, token: `SIM_TOKEN_${Date.now()}` };
309	      } else {
310	        setTapToPayStatus("idle");
311	        setShowTapToPayOverlay(false);
312	        toast({ title: "Not available", description: "Tap to Pay requires the TaptPay iOS app.", variant: "destructive" });
313	        return;
314	      }
315	      if (bridgeResult.cancelled) {
316	        setTapToPayStatus("idle");
317	        setShowTapToPayOverlay(false);
318	        toast({ title: "Cancelled", description: "Tap to Pay was cancelled." });
319	        return;
320	      }
321	      setTapToPayStatus("processing");
322	      const authToken = localStorage.getItem("authToken");
323	      const r = await fetch("/api/transactions/tap-to-pay", {
324	        method: "POST",
325	        headers: { "Content-Type": "application/json", Authorization: `Bearer ${authToken}` },
326	        body: JSON.stringify({
327	          merchantId,
328	          transactionId: tx.id,
329	          amount: parseFloat(tx.price),
330	          windcaveToken: bridgeResult.token,
331	        }),
332	      });
333	      if (!r.ok) {
334	        const errData = await r.json().catch(() => ({}));
335	        throw new Error(errData.message || `Processor error (${r.status})`);
336	      }
337	      const data = await r.json();
338	      setTapToPayApproved(data.approved);
339	      setTapToPayStatus(data.approved ? "completed" : "failed");
340	      queryClient.invalidateQueries({ queryKey: ["/api/merchants", merchantId, "active-transaction"] });
341	      setTimeout(() => { setShowTapToPayOverlay(false); setTapToPayStatus("idle"); setTapToPayApproved(null); }, 3500);
342	    } catch (err: any) {
343	      setTapToPayStatus("failed");
344	      setTapToPayApproved(false);
345	      toast({ title: "Payment error", description: err?.message || "Tap to Pay failed", variant: "destructive" });
346	    }
347	  };
348	
