409	    // Push the new transaction into the list cache immediately so it appears in the
410	    // active stack before the next background poll fires.
411	    queryClient.setQueryData<any[]>(
412	      ["/api/merchants", merchantId, "transactions"],
413	      (prev: any[] = []) => {
