1050	  /* Details commit */
1051	  const handleDetailsCommit = ({ name, amount }) => {
1052	    if (isLive) {
1053	      setLocalDraft({ name, amount, splitEnabled: pendingSplitEnabled });
1054	      setPendingSplitEnabled(false);
1055	    } else {
1056	      setState(s => ({ ...s, pending: { id: 'i' + Date.now(), name, amount } }));
1057	    }
1058	    go('home-pop');
1059	  };
1060	
1061	  /* Send: open customer payment page (live) or share screen (demo) */
1062	  const handleSend = async () => {
1063	    if (!state.pending) return;
1064	    if (isLive) {
1065	      if (!localDraft) {
1066	        if (paywaveOn) {
1067	          await onCreateSale?.(state.pending, { paywave: true, existing: true });
1068	        }
1069	        return;
1070	      }
1071	
1072	      const create = localDraft.splitEnabled ? (onCreateSplit ?? onCreateSale) : onCreateSale;
1073	      try {
1074	        await create?.(localDraft, { paywave: paywaveOn, existing: false });
1075	        setLocalDraft(null);
1076	      } catch {
1077	        /* draft preserved — error shown by parent */
1078	      }
1079	      return;
1080	    }
1081	
1082	    if (paywaveOn) {
1083	      toast('tap-to-pay (demo only)');
1084	      return;
1085	    }
1086	
1087	    // demo: show share screen
1088	    triggerConveyor('home', 'up');
1089	    setContentKey(k => k + 1);
1090	    setScreen('share');
1091	    setDockRaw('terminal');
1092	  };
1093	
1094	  /* Share screen ✓ confirm */
1095	  const handleShareConfirm = () => {
1096	    if (isLive) {
1097	      triggerConveyor('share', 'down');
1098	      setScreen('home');
1099	      setDockRaw('terminal');
1100	    } else {
1101	      setState(s => ({
1102	        ...s,
1103	        sent: [{ ...s.pending, status: 'sent' }, ...(s.sent || [])],
1104	        pending: null,
1105	      }));
1106	      triggerConveyor('share', 'down');
1107	      setScreen('home');
1108	      setDockRaw('terminal');
1109	    }
1110	  };
1111	
1112	  /* Cash entry commit → success screen */
1113	  const handleCashCommit = ({ name, amount }) => {
1114	    if (isLive) {
1115	      onCashSale?.({ name, amount });
1116	    } else {
1117	      setState(s => ({ ...s, pending: { id: 'i' + Date.now(), name, amount } }));
1118	    }
1119	    triggerConveyor('cash', 'up');
1120	    setScreen('cash-success');
1121	    setDockRaw('terminal');
1122	  };
1123	
1124	  /* Hold item restore (demo only) */
1125	  const handleStackItemClick = item => {
1126	    if (item.status !== 'hold' || isLive) return;
1127	    setState(s => ({ ...s, items: s.items.filter(i => i.id !== item.id), pending: { ...item } }));
1128	    setContentKey(k => k + 1);
1129	  };
1130	
1131	  const renderScreen = id => {
1132	    if (id.startsWith('dock-')) return <DockPlaceholder tab={id.slice(5)} />;
1133	    if (id === 'home') return state.pending
1134	      ? <PendingTerminal state={state} go={go} paywaveOn={paywaveOn} togglePaywave={() => setPaywaveOn(v => !v)} onItemClick={handleStackItemClick} showPaywave={showPaywave} onExpand={() => setStackExpanded(true)} onRowClick={it => { setSelectedStackTx(it); setShowTxRefundForm(false); }} />
1135	      : <MainTerminal    state={state} go={go} paywaveOn={paywaveOn} togglePaywave={() => setPaywaveOn(v => !v)} onItemClick={handleStackItemClick} showPaywave={showPaywave} onExpand={() => setStackExpanded(true)} onRowClick={it => { setSelectedStackTx(it); setShowTxRefundForm(false); }} />;
1136	    if (id === 'keypad')  return <Keypad       state={state} go={go} onCommit={handleCommit} />;
1137	    if (id === 'split')   return <SplitPayment state={state} go={go} onCommitSplit={handleSplitCommit} />;
1138	    if (id === 'stock')   return <ChooseStock  state={state} go={go} onCommitStock={handleStockCommit} />;
1139	    if (id === 'details') return <EnterDetails state={state} go={go} onCommitDetails={handleDetailsCommit} initialAmount={keypadCents} />;
1140	    if (id === 'share')   return <SharePayment state={state} go={go} toast={toast} onShare={onShare} onExpandQR={() => setShowQRModal(true)} onConfirmPayment={handleShareConfirm} livePayLink={livePayLink} qrElement={qrElement} />;
1141	    if (id === 'cash')         return <CashEntry   go={go} onCommitCash={handleCashCommit} />;
