1555	/* ── FAB ── */
1556	.tp-fab {
1557	  width: 70px; height: 70px; border-radius: 999px; background: #58ABFF; color: #040D6D;
1558	  display: flex; align-items: center; justify-content: center; box-shadow: 0 6px 18px rgba(4,13,109,0.25);
1559	  border: none; cursor: pointer; transition: transform 140ms; -webkit-tap-highlight-color: transparent;
1560	}
1561	.tp-fab:active { transform: scale(0.92); }
1562	
1563	/* ── Dock ── */
1564	.tp-dock-wrap { position: relative; margin: 0 auto 28px; width: 320px; height: 58px; display: flex; align-items: center; justify-content: center; overflow: visible; }
1565	.tp-dock {
1566	  position: relative; width: 280px; height: 48px; background: #040D6D; border-radius: 24px;
1567	  display: flex; align-items: center; justify-content: space-around; padding: 0 16px; overflow: visible;
1568	}
1569	.tp-dock-ind {
1570	  position: absolute; top: -5px; width: 65px; height: 58px; background: #040D6D; border-radius: 29px; z-index: 0;
1571	  box-shadow: 0 4px 20px rgba(0,0,0,0.45); pointer-events: none; will-change: left;
1572	}
1573	.tp-dock-ind.animate { transition: left 0.45s cubic-bezier(0.34,1.56,0.64,1); }
1574	.tp-dock-btn {
1575	  position: relative; z-index: 1; background: none; border: none; padding: 8px;
1576	  cursor: pointer; display: flex; align-items: center; justify-content: center;
1577	  transition: transform 0.25s ease; -webkit-tap-highlight-color: transparent;
1578	}
1579	.tp-dock-btn:active { transform: scale(0.95); }
1580	.tp-dock-btn.active { transform: scale(1.15); }
1581	
1582	/* ── Stack ── */
1583	.tp-stack-hdr { display: flex; justify-content: space-between; align-items: center; padding: 0 4px; margin-bottom: 12px; }
1584	.tp-stack-title { font-weight: 700; font-size: 14px; color: #040D6D; letter-spacing: -0.2px; }
1585	.tp-stack-card { border-radius: 14px; background: #fff; overflow: hidden; box-shadow: 0 2px 12px rgba(4,13,109,0.06); border: 1px solid rgba(4,13,109,0.04); }
1586	.tp-stack-row { display: flex; align-items: center; justify-content: space-between; padding: 14px 16px; animation: tp-stackIn 0.38s cubic-bezier(0.34,1.56,0.64,1) both; }
1587	.tp-stack-row + .tp-stack-row { border-top: 1px solid rgba(4,13,109,0.05); }
1588	@keyframes tp-stackIn { from { opacity:0; transform:translateY(-12px) scale(0.97); } to { opacity:1; transform:translateY(0) scale(1); } }
1589	.tp-stack-row.holdable { cursor: pointer; background: rgba(255,159,67,0.04); }
1590	.tp-stack-row.holdable:active { background: rgba(255,159,67,0.1); }
1591	.tp-stack-name   { font-weight: 600; font-size: 14px; color: #040D6D; margin-bottom: 1px; }
1592	.tp-stack-meta   { display: flex; align-items: center; gap: 5px; }
1593	.tp-stack-status { font-weight: 500; font-size: 11px; color: rgba(4,13,109,0.35); }
1594	.tp-stack-price  { font-weight: 700; font-size: 15px; color: #040D6D; letter-spacing: -0.3px; }
1595	.tp-stack-empty  { padding: 14px 16px; font-size: 13px; color: rgba(4,13,109,0.4); text-align: center; }
1596	.tp-hold-hint    { font-size: 10px; font-weight: 600; color: #FF9F43; }
1597	.tp-dot { width: 5px; height: 5px; border-radius: 50%; animation: tp-pulse 2s ease-in-out infinite; }
1598	.tp-dot.awaiting     { background: #58ABFF; }
1599	.tp-dot.payment-sent { background: #58ABFF; }
1600	.tp-dot.paid         { background: #1BBF85; animation: none; opacity: 1; }
1601	.tp-dot.declined     { background: #FF5B5B; animation: none; opacity: 1; }
1602	.tp-dot.hold         { background: #FF9F43; }
1603	@keyframes tp-pulse { 0%,100% { opacity:0.4; } 50% { opacity:1; } }
1604	.tp-stack-split       { display: flex; flex-direction: column; gap: 5px; margin-top: 5px; padding: 6px 8px; background: rgba(4,13,109,0.04); border-radius: 8px; border-left: 3px solid #58ABFF; }
1605	.tp-stack-split-label { font-size: 9px; font-weight: 800; color: #58ABFF; letter-spacing: 0.6px; text-transform: uppercase; }
1606	.tp-stack-split-bars  { display: flex; gap: 4px; align-items: center; }
1607	.tp-split-bar         { height: 7px; flex: 1; border-radius: 4px; background: rgba(4,13,109,0.1); }
1608	.tp-split-bar.filled  { background: #1BBF85; }
1609	.tp-stack-split-dots  { display: flex; gap: 5px; align-items: center; }
1610	.tp-split-dot         { width: 8px; height: 8px; border-radius: 50%; background: rgba(4,13,109,0.12); border: 1.5px solid rgba(4,13,109,0.15); }
1611	.tp-split-dot.filled  { background: #1BBF85; border-color: #1BBF85; }
1612	.tp-stack-split-count { font-size: 12px; font-weight: 700; color: #040D6D; }
1613	
1614	/* ── Stock tiles ── */
1615	.tp-stock-tile {
1616	  aspect-ratio: 1/1; background: #F4F4F4; border-radius: 22px; border: none; cursor: pointer;
1617	  transition: transform 120ms, box-shadow 120ms; position: relative;
1618	}
1619	.tp-stock-tile:active { transform: scale(0.95); }
1620	.tp-stock-tile.selected { box-shadow: inset 0 0 0 3px #58ABFF; }
1621	.tp-stock-qty {
1622	  position: absolute; top: 7px; right: 7px;
1623	  min-width: 20px; height: 20px; border-radius: 999px;
1624	  background: #040D6D; color: #58ABFF;
1625	  font-size: 11px; font-weight: 800; display: flex; align-items: center; justify-content: center;
1626	  padding: 0 5px;
1627	}
1628	
1629	/* ── Fields ── */
1630	.tp-field {
1631	  width: 100%; padding: 18px 24px; border-radius: 999px;
1632	  background: #F4F4F4; border: none; color: #040D6D;
1633	  font-family: 'Outfit', system-ui; font-weight: 500; font-size: 17px;
1634	  letter-spacing: -0.01em; outline: none; box-sizing: border-box;
1635	}
1636	.tp-field::placeholder { color: rgba(4,13,109,0.35); }
1637	
1638	/* ── CTA ── */
1639	.tp-cta {
1640	  display: inline-flex; align-items: center; justify-content: center;
1641	  padding: 14px 36px; border-radius: 999px; background: #58ABFF; color: #040D6D;
1642	  font-family: 'Outfit', system-ui; font-weight: 600; font-size: 15px;
1643	  transition: transform 120ms, opacity 120ms; white-space: nowrap; border: none; cursor: pointer; box-sizing: border-box;
1644	}
1645	.tp-cta:active { transform: scale(0.96); opacity: 0.92; }
1646	
1647	/* ── Stepper ── */
1648	.tp-stepper {
1649	  width: 44px; height: 44px; border-radius: 999px; background: #58ABFF; color: #040D6D;
1650	  display: flex; align-items: center; justify-content: center;
1651	  font-size: 22px; font-weight: 700; border: none; cursor: pointer; transition: transform 100ms;
1652	}
1653	.tp-stepper:active { transform: scale(0.92); }
1654	
1655	/* ── Keypad ── */
1656	.tp-kp {
1657	  width: 76px; height: 76px; border-radius: 999px;
1658	  display: flex; align-items: center; justify-content: center;
1659	  font-family: 'Outfit', system-ui; font-weight: 700; font-size: 30px;
1660	  transition: transform 100ms, background 100ms; background: #58ABFF; color: #fff; border: none; cursor: pointer;
1661	}
1662	.tp-kp:active { transform: scale(0.92); }
1663	.tp-kp.outline { background: transparent; color: #58ABFF; box-shadow: inset 0 0 0 2px #58ABFF; }
1664	.tp-kp.outline:active { background: rgba(88,171,255,0.12); }
1665	
1666	/* ── QR ── */
1667	.tp-qr-card { width: 220px; height: 220px; border-radius: 28px; background: #040D6D; box-shadow: inset 0 0 0 4px #58ABFF; display: flex; align-items: center; justify-content: center; overflow: hidden; }
1668	.tp-qr-expand {
1669	  position: absolute; bottom: 10px; right: 10px; width: 30px; height: 30px; border-radius: 50%;
1670	  background: rgba(4,13,109,0.55); border: 1.5px solid #58ABFF; color: #58ABFF;
1671	  display: flex; align-items: center; justify-content: center; cursor: pointer; transition: transform 0.18s, background 0.18s;
1672	}
1673	.tp-qr-expand:active { transform: scale(0.88); background: rgba(88,171,255,0.25); }
1674	.tp-qr-modal {
1675	  position: absolute; inset: 0; z-index: 50;
1676	  background: rgba(4,13,109,0.82); backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
1677	  display: flex; align-items: center; justify-content: center; animation: tp-fadeIn 0.22s ease both;
1678	}
1679	.tp-qr-modal-inner {
1680	  position: relative; background: #040D6D; border-radius: 36px;
1681	  padding: 36px 36px 28px; border: 3px solid #58ABFF;
1682	  box-shadow: 0 28px 80px rgba(4,13,109,0.7);
1683	  animation: tp-scaleIn 0.4s cubic-bezier(0.34,1.56,0.64,1) both;
1684	  display: flex; flex-direction: column; align-items: center;
1685	}
1686	.tp-qr-modal-close {
1687	  position: absolute; top: 14px; right: 14px; width: 32px; height: 32px; border-radius: 50%;
1688	  border: 1.5px solid rgba(88,171,255,0.5); color: #58ABFF; background: none; cursor: pointer;
1689	  display: flex; align-items: center; justify-content: center; transition: background 0.15s, transform 0.15s;
1690	}
1691	.tp-qr-modal-close:active { background: rgba(88,171,255,0.15); transform: scale(0.9); }
1692	@keyframes tp-fadeIn  { from { opacity: 0; } to { opacity: 1; } }
1693	@keyframes tp-scaleIn { from { opacity: 0; transform: scale(0.6); } to { opacity: 1; transform: scale(1); } }
1694	
1695	/* ── Share buttons ── */
1696	.tp-share-btn {
1697	  background: none; border: none; cursor: pointer; padding: 8px;
1698	  display: flex; align-items: center; justify-content: center;
1699	  transition: transform 0.15s, opacity 0.15s; border-radius: 50%; -webkit-tap-highlight-color: transparent;
1700	}
1701	.tp-share-btn:active { transform: scale(0.85); opacity: 0.65; }
1702	
1703	/* ── Success check ── */
1704	.tp-success-check { width: 92px; height: 92px; border-radius: 999px; background: #58ABFF; display: flex; align-items: center; justify-content: center; color: #040D6D; }
1705	.tp-pulse { animation: tp-pulseDot 1800ms ease-in-out infinite; }
1706	@keyframes tp-pulseDot { 0%,100% { transform:scale(1); opacity:1; } 50% { transform:scale(1.08); opacity:0.85; } }
1707	
1708	/* ── Scroll ── */
1709	.tp-thin-scroll { scrollbar-width: thin; scrollbar-color: rgba(88,171,255,0) transparent; transition: scrollbar-color 350ms; }
1710	.tp-thin-scroll.scrolling { scrollbar-color: #58ABFF transparent; }
1711	.tp-thin-scroll::-webkit-scrollbar { width: 3px; }
1712	.tp-thin-scroll::-webkit-scrollbar-thumb { background-color: rgba(88,171,255,0); border-radius: 999px; }
1713	.tp-thin-scroll.scrolling::-webkit-scrollbar-thumb { background-color: #58ABFF; }
1714	/* Stack scroll — navy thumb, no track, no arrows */
1715	.tp-stack-scroll { scrollbar-width: thin; scrollbar-color: #040D6D transparent; }
1716	.tp-stack-scroll::-webkit-scrollbar { width: 4px; background: transparent; }
1717	.tp-stack-scroll::-webkit-scrollbar-track { background: transparent; }
1718	.tp-stack-scroll::-webkit-scrollbar-thumb { background: #040D6D; border-radius: 999px; }
1719	.tp-stack-scroll::-webkit-scrollbar-button { display: none; height: 0; width: 0; }
1720	
1721	/* ── Toast ── */
1722	.tp-toast {
1723	  position: absolute; left: 50%; transform: translateX(-50%); bottom: 28px;
1724	  background: #040D6D; color: #F4F4F4; padding: 12px 22px; border-radius: 999px;
1725	  font-size: 14px; font-weight: 500; opacity: 0; pointer-events: none;
1726	  transition: opacity 200ms, transform 200ms; z-index: 60;
1727	}
1728	.tp-toast.show { opacity: 1; transform: translateX(-50%) translateY(-4px); }
1729	
1730	/* ── Conveyor ── */
1731	.tp-layer { position: absolute; inset: 0; display: flex; flex-direction: column; overflow: hidden; will-change: transform; z-index: 0; }
1732	.tp-layer.leaving.up   { animation: tp-outUp   0.48s cubic-bezier(0.4,0,0.2,1) both; z-index: 1; }
1733	.tp-layer.leaving.down { animation: tp-outDown 0.48s cubic-bezier(0.4,0,0.2,1) both; z-index: 1; }
1734	.tp-layer.entering.up   { animation: tp-inUp   0.48s cubic-bezier(0.16,1,0.3,1) both; }
1735	.tp-layer.entering.down { animation: tp-inDown 0.48s cubic-bezier(0.16,1,0.3,1) both; }
1736	.tp-layer.leaving.morph { animation: tp-outMorph 0.22s ease-out both; z-index: 1; }
1737	@keyframes tp-outMorph { from { opacity: 1; } to { opacity: 0; } }
1738	@keyframes tp-inUp    { from { transform: translateY(100%);  } to { transform: translateY(0); } }
1739	@keyframes tp-outUp   { from { transform: translateY(0);     } to { transform: translateY(-100%); } }
1740	@keyframes tp-inDown  { from { transform: translateY(-100%); } to { transform: translateY(0); } }
1741	@keyframes tp-outDown { from { transform: translateY(0);     } to { transform: translateY(100%); } }
1742	
1743	/* ── popIn ── */
1744	@keyframes tp-popIn { from { opacity:0; transform:translateY(16px) scale(0.96); } to { opacity:1; transform:translateY(0) scale(1); } }
1745	.stagger { transition: height 0.55s cubic-bezier(0.34,1.56,0.64,1); }
1746	.stagger > * { animation: tp-popIn 0.4s cubic-bezier(0.34,1.56,0.64,1) both; }
1747	.stagger > *:nth-child(1) { animation-delay: 0s; }
1748	.stagger > *:nth-child(2) { animation-delay: 0.06s; }
1749	.stagger > *:nth-child(3) { animation-delay: 0.12s; }
1750	.stagger > *:nth-child(4) { animation-delay: 0.18s; }
1751	.stagger > *:nth-child(5) { animation-delay: 0.24s; }
1752	.stagger > *:nth-child(6) { animation-delay: 0.30s; }
1753	
1754	/* ── Overlay ── */
1755	.tp-overlay { position: absolute; inset: 0; pointer-events: none; z-index: 30; }
1756	.tp-overlay > * { pointer-events: auto; }
1757	.tp-pfab {
1758	  position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
1759	  transition: opacity 240ms cubic-bezier(0,0,0.2,1), transform 360ms cubic-bezier(0.34,1.56,0.64,1);
1760	  will-change: opacity, transform;
1761	}
1762	.tp-pfab.hide { opacity: 0; transform: translate(-50%, -50%) translateY(8px) scale(0.7); pointer-events: none; }
1763	.tp-pfab.show { opacity: 1; }
1764	.tp-psubbar {
1765	  position: absolute; top: 50%; left: 50%; transform: translate(-50%, 67px);
1766	  display: flex; align-items: center; gap: 8px;
1767	  transition: opacity 220ms cubic-bezier(0,0,0.2,1), transform 300ms cubic-bezier(0.4,0,0.2,1);
1768	  will-change: opacity, transform;
1769	  height: 37px;
1770	}
1771	.tp-psubbar.hide    { opacity: 0; transform: translate(-50%, 67px) scale(0.92); pointer-events: none; }
1772	.tp-psubbar.show    { opacity: 1; }
1773	.tp-psubbar.feature { transform: translate(-50%, calc(-100% - 20px)); }
1774	.tp-send-slot {
1775	  display: flex; align-items: center; overflow: hidden; max-width: 0; opacity: 0;
1776	  transition: max-width 420ms cubic-bezier(0.34,1.56,0.64,1), opacity 280ms ease 80ms;
1777	  height: 37px;
1778	}
1779	.tp-send-slot.show { max-width: 143px; opacity: 1; }
1780	.tp-pdock {
1781	  position: absolute; left: 0; right: 0; bottom: 0; display: flex; justify-content: center;
1782	  transition: opacity 280ms cubic-bezier(0,0,0.2,1), transform 360ms cubic-bezier(0.34,1.56,0.64,1);
1783	  will-change: opacity, transform;
1784	}
1785	.tp-pdock.hide { opacity: 0; transform: translateY(24px); pointer-events: none; }
1786	.tp-pdock.show { opacity: 1; transform: translateY(0); }
1787	`;
