/* Focused probe: amount overflow, split-bill pill vs action bar, matched CSS rules. */
import { chromium } from "playwright";
import { mkdir } from "node:fs/promises";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "../scripts/desktop-shots/retail-fixtures.mjs";

const OUT = "/tmp/claude-1000/-home-runner-workspace/77407836-b974-40ea-96f0-bff2e237e95e/scratchpad/shots2";

const PHONES = [
  ["se1-320x568", 320, 568],
  ["se2-375x667", 375, 667],
  ["ip14-390x844", 390, 844],
  ["ipmax-430x932", 430, 932],
];

const whyRules = (selector, props) => {
  const el = document.querySelector(selector);
  if (!el) return null;
  const hits = [];
  for (const sheet of document.styleSheets) {
    let rules;
    try { rules = sheet.cssRules; } catch { continue; }
    const walk = (list, media) => {
      for (const rule of list) {
        if (rule.media) { walk(rule.cssRules, rule.conditionText || String(rule.media.mediaText)); continue; }
        if (!rule.selectorText) continue;
        let matches = false;
        try { matches = el.matches(rule.selectorText); } catch { continue; }
        if (!matches) continue;
        for (const p of props) {
          const v = rule.style.getPropertyValue(p);
          if (v) hits.push({ media, selector: rule.selectorText, prop: p, value: v, important: rule.style.getPropertyPriority(p) });
        }
      }
    };
    walk(rules, null);
  }
  return hits;
};

const amountProbe = () => {
  const el = document.querySelector(".tp-amount");
  if (!el) return null;
  const parent = el.parentElement;
  const cs = getComputedStyle(el);
  // measure the natural text width with a canvas
  const c = document.createElement("canvas").getContext("2d");
  c.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
  const textW = c.measureText(el.textContent).width;
  const pcs = getComputedStyle(parent);
  return {
    text: el.textContent,
    fontSize: cs.fontSize,
    whiteSpace: cs.whiteSpace,
    boxW: +el.getBoundingClientRect().width.toFixed(1),
    scrollW: el.scrollWidth,
    clientW: el.clientWidth,
    naturalTextW: +textW.toFixed(1),
    parentInnerW: +(parent.clientWidth - parseFloat(pcs.paddingLeft) - parseFloat(pcs.paddingRight)).toFixed(1),
    overflowPx: +(textW - (parent.clientWidth - parseFloat(pcs.paddingLeft) - parseFloat(pcs.paddingRight))).toFixed(1),
    rect: (({ x, y, width, height, right }) => ({ x: +x.toFixed(1), y: +y.toFixed(1), w: +width.toFixed(1), h: +height.toFixed(1), right: +right.toFixed(1) }))(el.getBoundingClientRect()),
  };
};

const barProbe = () => {
  const r = (s) => {
    const el = typeof s === "string" ? document.querySelector(s) : s;
    if (!el) return null;
    const b = el.getBoundingClientRect();
    return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1), bottom: +b.bottom.toFixed(1), right: +b.right.toFixed(1) };
  };
  const psub = document.querySelector(".tp-psubbar");
  const sub = document.querySelector(".tp-subbar");
  const pill = document.querySelector('[data-demo-id="retail-split-toggle"]');
  const send = document.querySelector(".tp-send");
  const cs = (s, p) => { const e = document.querySelector(s); return e ? getComputedStyle(e)[p] : null; };
  const overlap = (a, b) => {
    if (!a || !b) return null;
    const dy = Math.min(a.bottom, b.bottom) - Math.max(a.y, b.y);
    const dx = Math.min(a.right, b.right) - Math.max(a.x, b.x);
    return dy > 0 && dx > 0 ? { x: +dx.toFixed(1), y: +dy.toFixed(1) } : null;
  };
  const pr = r(pill), sr = r(sub), psr = r(psub);
  return {
    psubbar: psr, psubbarCssH: cs(".tp-psubbar", "height"),
    psubbarScrollW: psub ? psub.scrollWidth : null,
    psubbarClientW: psub ? psub.clientWidth : null,
    subbar: sr, subbarOverflowsPsubbar: psr && sr ? +(sr.h - psr.h).toFixed(1) : null,
    ind: r(".tp-subbar-ind"), indH: cs(".tp-subbar-ind", "height"),
    btnH: cs(".tp-subbar-btn", "height"),
    btn: r(".tp-subbar-btn"),
    activeBtn: r(".tp-subbar-btn.active"),
    label: r(".tp-subbar-label"),
    labelInsideInd: (() => {
      const l = r(".tp-subbar-label"), i = r(".tp-subbar-ind");
      if (!l || !i) return null;
      return { topGap: +(l.y - i.y).toFixed(1), bottomGap: +(i.bottom - l.bottom).toFixed(1) };
    })(),
    send: r(send), sendCssH: cs(".tp-send", "height"),
    splitPill: pr, splitPillCssH: pill ? getComputedStyle(pill).height : null,
    splitPillMinH: pill ? getComputedStyle(pill).minHeight : null,
    pillVsBarOverlap: overlap(pr, psr),
    pillVsSubbarOverlap: overlap(pr, sr),
  };
};

async function run() {
  await mkdir(OUT, { recursive: true });
  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
  const out = [];
  try {
    for (const [label, width, height] of PHONES) {
      const { context, page } = await newRetailPage(browser, label, {
        viewport: { width, height }, hasTouch: true, isMobile: true, deviceScaleFactor: 2,
      });
      await page.goto(`${BASE_URL}/terminal`, { waitUntil: "networkidle" });
      await page.waitForSelector(".tp-viewport", { timeout: 15000 });
      await page.waitForTimeout(1200);

      const rules = await page.evaluate(
        ([sel, props]) => whyRulesFn(sel, props),
        null,
      ).catch(() => null);

      const btnRules = await page.evaluate(whyRules, [".tp-subbar-btn", ["height", "min-height", "min-width"]]).catch((e) => String(e));

      // open keypad
      await page.click('[data-demo-id="retail-add-sale"]');
      await page.waitForTimeout(800);
      const keypadIdle = { amount: await page.evaluate(amountProbe), bar: await page.evaluate(barProbe) };
      await page.screenshot({ path: `${OUT}/${label}-keypad-idle.png` });

      // enter a big amount: 9999999 cents => $99999.99
      for (const d of ["9", "9", "9", "9", "9", "9", "9"]) {
        await page.click(`[data-demo-id="retail-key-${d}"]`);
      }
      await page.waitForTimeout(400);
      const keypadBig = { amount: await page.evaluate(amountProbe), bar: await page.evaluate(barProbe) };
      await page.screenshot({ path: `${OUT}/${label}-keypad-big.png` });

      // toggle split bill on
      await page.click('[data-demo-id="retail-split-toggle"]');
      await page.waitForTimeout(400);
      const splitOn = await page.evaluate(barProbe);
      await page.screenshot({ path: `${OUT}/${label}-keypad-split-on.png` });

      // click the split entry in the action bar
      await page.click('[data-demo-id="retail-mode-split"]');
      await page.waitForTimeout(900);
      const splitScreen = await page.evaluate(barProbe);
      await page.screenshot({ path: `${OUT}/${label}-split-screen.png` });

      out.push({ label, width, height, btnRules, keypadIdle, keypadBig, splitOn, splitScreen });
      await context.close();
    }
  } finally {
    await browser.close();
  }
  console.log(JSON.stringify(out, null, 1));
}

run().catch((e) => { console.error(e); process.exit(1); });

