40	const amountProbe = () => {
41	  const el = document.querySelector(".tp-amount");
42	  if (!el) return null;
43	  const parent = el.parentElement;
44	  const cs = getComputedStyle(el);
45	  // measure the natural text width with a canvas
46	  const c = document.createElement("canvas").getContext("2d");
47	  c.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
48	  const textW = c.measureText(el.textContent).width;
49	  const pcs = getComputedStyle(parent);
50	  return {
51	    text: el.textContent,
52	    fontSize: cs.fontSize,
53	    whiteSpace: cs.whiteSpace,
54	    boxW: +el.getBoundingClientRect().width.toFixed(1),
55	    scrollW: el.scrollWidth,
56	    clientW: el.clientWidth,
57	    naturalTextW: +textW.toFixed(1),
58	    parentInnerW: +(parent.clientWidth - parseFloat(pcs.paddingLeft) - parseFloat(pcs.paddingRight)).toFixed(1),
59	    overflowPx: +(textW - (parent.clientWidth - parseFloat(pcs.paddingLeft) - parseFloat(pcs.paddingRight))).toFixed(1),
60	    rect: (({ x, y, width, height, right }) => ({ x: +x.toFixed(1), y: +y.toFixed(1), w: +width.toFixed(1), h: +height.toFixed(1), right: +right.toFixed(1) }))(el.getBoundingClientRect()),
61	  };
62	};
63	
64	const barProbe = () => {
65	  const r = (s) => {
66	    const el = typeof s === "string" ? document.querySelector(s) : s;
67	    if (!el) return null;
68	    const b = el.getBoundingClientRect();
69	    return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1), bottom: +b.bottom.toFixed(1), right: +b.right.toFixed(1) };
70	  };
71	  const psub = document.querySelector(".tp-psubbar");
72	  const sub = document.querySelector(".tp-subbar");
73	  const pill = document.querySelector('[data-demo-id="retail-split-toggle"]');
74	  const send = document.querySelector(".tp-send");
75	  const cs = (s, p) => { const e = document.querySelector(s); return e ? getComputedStyle(e)[p] : null; };
76	  const overlap = (a, b) => {
77	    if (!a || !b) return null;
78	    const dy = Math.min(a.bottom, b.bottom) - Math.max(a.y, b.y);
79	    const dx = Math.min(a.right, b.right) - Math.max(a.x, b.x);
80	    return dy > 0 && dx > 0 ? { x: +dx.toFixed(1), y: +dy.toFixed(1) } : null;
81	  };
82	  const pr = r(pill), sr = r(sub), psr = r(psub);
83	  return {
84	    psubbar: psr, psubbarCssH: cs(".tp-psubbar", "height"),
