86	    psubbarClientW: psub ? psub.clientWidth : null,
87	    subbar: sr, subbarOverflowsPsubbar: psr && sr ? +(sr.h - psr.h).toFixed(1) : null,
88	    ind: r(".tp-subbar-ind"), indH: cs(".tp-subbar-ind", "height"),
89	    btnH: cs(".tp-subbar-btn", "height"),
90	    btn: r(".tp-subbar-btn"),
91	    activeBtn: r(".tp-subbar-btn.active"),
92	    label: r(".tp-subbar-label"),
93	    labelInsideInd: (() => {
