95	      if (!l || !i) return null;
96	      return { topGap: +(l.y - i.y).toFixed(1), bottomGap: +(i.bottom - l.bottom).toFixed(1) };
97	    })(),
98	    send: r(send), sendCssH: cs(".tp-send", "height"),
99	    splitPill: pr, splitPillCssH: pill ? getComputedStyle(pill).height : null,
100	    splitPillMinH: pill ? getComputedStyle(pill).minHeight : null,
101	    pillVsBarOverlap: overlap(pr, psr),
102	    pillVsSubbarOverlap: overlap(pr, sr),
103	  };
