129	        await page.click(`[data-demo-id="retail-key-${d}"]`);
130	      }
131	      await page.waitForTimeout(400);
132	      const keypadBig = { amount: await page.evaluate(amountProbe), bar: await page.evaluate(barProbe) };
133	      await page.screenshot({ path: `${OUT}/${label}-keypad-big.png` });
134	
135	      // toggle split bill on
136	      await page.click('[data-demo-id="retail-split-toggle"]');
137	      await page.waitForTimeout(400);
138	      const splitOn = await page.evaluate(barProbe);
139	      await page.screenshot({ path: `${OUT}/${label}-keypad-split-on.png` });
140	
141	      // click the split entry in the action bar
142	      await page.click('[data-demo-id="retail-mode-split"]');
143	      await page.waitForTimeout(900);
144	      const splitScreen = await page.evaluate(barProbe);
145	      await page.screenshot({ path: `${OUT}/${label}-split-screen.png` });
146	
147	      out.push({ label, width, height, btnRules, keypadIdle, keypadBig, splitOn, splitScreen });
148	      await context.close();
149	    }
150	  } finally {
151	    await browser.close();
152	  }
153	  console.log(JSON.stringify(out, null, 1));
154	}
155	
156	run().catch((e) => { console.error(e); process.exit(1); });

