/* Sweep: (a) app-wide mobile overflow + forced-button-size audit across every
 * merchant mobile page and 3 phone sizes; (b) cross-vertical CSS collision test. */
import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "../scripts/desktop-shots/retail-fixtures.mjs";

const PHONES = [
  ["320x568", 320, 568],
  ["390x844", 390, 844],
  ["430x932", 430, 932],
];

const ROUTES = [
  "/terminal", "/dashboard", "/stock", "/transactions", "/settings",
  "/property", "/property/terminal", "/property/tenants",
  "/trades", "/trades/terminal", "/trades/clients",
];

const audit = () => {
  const vw = document.documentElement.clientWidth;
  const out = { docScrollW: document.documentElement.scrollWidth, vw, overflowX: [], forcedButtons: [], clippedText: [] };

  const all = document.querySelectorAll("body *");
  for (const el of all) {
    const b = el.getBoundingClientRect();
    if (b.width === 0 || b.height === 0) continue;
    const cs = getComputedStyle(el);
    if (cs.position === "fixed" && b.width > vw + 1) { /* full-bleed overlays fine */ }
    // horizontal overflow past the visual viewport
    if (b.right > vw + 1.5 || b.left < -1.5) {
      if (cs.visibility !== "hidden" && cs.opacity !== "0") {
        out.overflowX.push({
          tag: el.tagName.toLowerCase(),
          cls: (el.className && el.className.baseVal !== undefined ? el.className.baseVal : String(el.className || "")).slice(0, 60),
          left: +b.left.toFixed(1), right: +b.right.toFixed(1), w: +b.width.toFixed(1),
        });
      }
    }
    // author height overridden by the global min-height
    if (el.tagName === "BUTTON" || el.getAttribute("role") === "button") {
      const mh = parseFloat(cs.minHeight) || 0;
      const mw = parseFloat(cs.minWidth) || 0;
      if ((mh >= 44 && b.height <= mh + 0.5 && b.height >= mh - 0.5) || (mw >= 44 && b.width <= mw + 0.5 && b.width >= mw - 0.5)) {
        // only report ones whose inline/author height differs
        const authorH = el.style.height || null;
        out.forcedButtons.push({
          cls: String(el.className || "").slice(0, 50),
          label: (el.getAttribute("aria-label") || el.textContent || "").trim().slice(0, 24),
          h: +b.height.toFixed(1), w: +b.width.toFixed(1), authorH, minH: cs.minHeight, minW: cs.minWidth,
        });
      }
    }
    // text clipped by an overflow:hidden ancestor of smaller size
    if (el.children.length === 0 && el.textContent && el.textContent.trim() && el.scrollWidth > el.clientWidth + 2) {
      out.clippedText.push({
        cls: String(el.className || "").slice(0, 40),
        text: el.textContent.trim().slice(0, 24),
        scrollW: el.scrollWidth, clientW: el.clientWidth,
      });
    }
  }
  out.forcedButtonCount = out.forcedButtons.length;
  out.forcedButtons = out.forcedButtons.slice(0, 8);
  out.overflowXCount = out.overflowX.length;
  out.overflowX = out.overflowX.slice(0, 8);
  out.clippedTextCount = out.clippedText.length;
  out.clippedText = out.clippedText.slice(0, 6);
  return out;
};

const subbarGeom = () => {
  const sub = document.querySelector(".tp-subbar");
  const ind = document.querySelector(".tp-subbar-ind");
  const btn = document.querySelector(".tp-subbar-btn");
  const styles = [...document.querySelectorAll("style")].map((s, i) => ({
    i, len: s.textContent.length, hasSubbar: s.textContent.includes(".tp-subbar {"),
    scoped: s.textContent.includes("trades-terminal-view"),
    scale: (s.textContent.match(/\.tp-subbar \{[^}]*transform: scale\(([\d.]+)\)/) || [])[1] || null,
  })).filter((s) => s.hasSubbar);
  return {
    styleTagsDefiningSubbar: styles,
    subbarTransform: sub ? getComputedStyle(sub).transform : null,
    subbarRect: sub ? { w: +sub.getBoundingClientRect().width.toFixed(1), h: +sub.getBoundingClientRect().height.toFixed(1) } : null,
    indH: ind ? getComputedStyle(ind).height : null,
    indZ: ind ? getComputedStyle(ind).zIndex : null,
    btnH: btn ? getComputedStyle(btn).height : null,
    btnPad: btn ? getComputedStyle(btn).padding : null,
  };
};

async function run() {
  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
  const report = { sweep: [], collision: null };
  try {
    for (const [label, width, height] of PHONES) {
      const { context, page } = await newRetailPage(browser, `sweep-${label}`, {
        viewport: { width, height }, hasTouch: true, isMobile: true, deviceScaleFactor: 1,
      });
      for (const route of ROUTES) {
        await page.goto(`${BASE_URL}${route}`, { waitUntil: "domcontentloaded" });
        await page.waitForTimeout(1500);
        const a = await page.evaluate(audit);
        report.sweep.push({ phone: label, route, ...a });
      }
      await context.close();
    }

    // collision: mount property terminal, then navigate to retail terminal in-app
    const { context, page } = await newRetailPage(browser, "collision", {
      viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 1,
    });
    await page.goto(`${BASE_URL}/terminal`, { waitUntil: "domcontentloaded" });
    await page.waitForTimeout(1500);
    const before = await page.evaluate(subbarGeom);
    await page.goto(`${BASE_URL}/property/terminal`, { waitUntil: "domcontentloaded" });
    await page.waitForTimeout(1800);
    const property = await page.evaluate(subbarGeom);
    // in-app SPA nav back to retail via the dock
    await page.click('[data-demo-id="dock-home"]').catch(() => {});
    await page.waitForTimeout(400);
    const midTransition = await page.evaluate(subbarGeom);
    await page.waitForTimeout(1800);
    await page.goto(`${BASE_URL}/terminal`, { waitUntil: "domcontentloaded" });
    await page.waitForTimeout(1500);
    const after = await page.evaluate(subbarGeom);
    report.collision = { before, property, midTransition, after };
    await context.close();
  } finally {
    await browser.close();
  }
  console.log(JSON.stringify(report, null, 1));
}

run().catch((e) => { console.error(e); process.exit(1); });

