import { chromium } from "playwright";
import { mkdir } from "node:fs/promises";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "../scripts/desktop-shots/retail-fixtures.mjs";

const OUT = "/tmp/claude-1000/-home-runner-workspace/77407836-b974-40ea-96f0-bff2e237e95e/scratchpad/shots4";
const PHONES = [["320x568", 320, 568], ["375x667", 375, 667], ["390x844", 390, 844], ["430x932", 430, 932]];

const bar = () => {
  const vw = document.documentElement.clientWidth;
  const r = (s) => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect();
    return { x: +b.x.toFixed(1), right: +b.right.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) }; };
  const psub = document.querySelector(".tp-psubbar");
  return {
    vw,
    psubbar: r(".tp-psubbar"), psubbarScrollW: psub?.scrollWidth, psubbarClientW: psub?.clientWidth,
    subbar: r(".tp-subbar"), send: r(".tp-send"), slot: r(".tp-send-slot"),
    slotMaxW: document.querySelector(".tp-send-slot") ? getComputedStyle(document.querySelector(".tp-send-slot")).maxWidth : null,
    sendOffscreenBy: (() => { const e = document.querySelector(".tp-send"); if (!e) return null;
      return +(e.getBoundingClientRect().right - vw).toFixed(1); })(),
    sendClickable: (() => {
      const e = document.querySelector(".tp-send"); if (!e) return null;
      const b = e.getBoundingClientRect();
      const cx = Math.min(Math.max(b.x + b.width / 2, 1), vw - 1), cy = b.y + b.height / 2;
      const hit = document.elementFromPoint(cx, cy);
      return !!(hit && (hit === e || e.contains(hit)));
    })(),
  };
};

const settingsOverflow = () => {
  const vw = document.documentElement.clientWidth;
  const hits = [];
  for (const el of document.querySelectorAll("body *")) {
    const b = el.getBoundingClientRect();
    if (b.width === 0 || b.height === 0) continue;
    if (b.right > vw + 1.5 || b.left < -1.5) {
      const cs = getComputedStyle(el);
      if (cs.visibility === "hidden" || cs.opacity === "0") continue;
      hits.push({ tag: el.tagName.toLowerCase(), cls: String(el.className || "").slice(0, 70),
        text: (el.textContent || "").trim().slice(0, 30), x: +b.x.toFixed(1), right: +b.right.toFixed(1), w: +b.width.toFixed(1) });
    }
  }
  return hits.slice(0, 10);
};

async function run() {
  await mkdir(OUT, { recursive: true });
  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
  const out = [];
  try {
    for (const [label, width, height] of PHONES) {
      const { context, page } = await newRetailPage(browser, label, {
        viewport: { width, height }, hasTouch: true, isMobile: true, deviceScaleFactor: 2,
      });
      await page.goto(`${BASE_URL}/terminal`, { waitUntil: "domcontentloaded" });
      await page.waitForSelector(".tp-viewport"); await page.waitForTimeout(1300);

      // build a pending sale: FAB -> keypad -> 550 -> commit -> details -> name -> confirm
      await page.click('[data-demo-id="retail-add-sale"]'); await page.waitForTimeout(700);
      for (const d of ["5", "5", "0"]) await page.click(`[data-demo-id="retail-key-${d}"]`);
      await page.click('[data-demo-id="retail-keypad-confirm"]'); await page.waitForTimeout(800);
      await page.fill('[data-demo-id="retail-item-name"]', "flat white").catch(() => {});
      await page.click('[data-demo-id="retail-details-confirm"]').catch(() => {});
      await page.waitForTimeout(1200);
      const pending = await page.evaluate(bar);
      await page.screenshot({ path: `${OUT}/${label}-pending.png` });

      await page.goto(`${BASE_URL}/settings`, { waitUntil: "domcontentloaded" });
      await page.waitForTimeout(1800);
      const settings = await page.evaluate(settingsOverflow);
      await page.screenshot({ path: `${OUT}/${label}-settings.png`, fullPage: false });

      out.push({ label, width, pending, settings });
      await context.close();
    }
  } finally { await browser.close(); }
  console.log(JSON.stringify(out, null, 1));
}
run().catch((e) => { console.error(e); process.exit(1); });

