import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "../scripts/desktop-shots/retail-fixtures.mjs";
const m = () => {
  const r = (s) => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect();
    return { h: +b.height.toFixed(1), w: +b.width.toFixed(1) }; };
  const hdrBtn = document.querySelector('[data-demo-id="retail-stack-expand"]');
  return {
    hdr: r(".tp-stack-hdr"), hdrTitle: r(".tp-stack-title"),
    hdrBtn: hdrBtn ? { h: +hdrBtn.getBoundingClientRect().height.toFixed(1), w: +hdrBtn.getBoundingClientRect().width.toFixed(1), minH: getComputedStyle(hdrBtn).minHeight, minW: getComputedStyle(hdrBtn).minWidth } : null,
    row: r(".tp-stack-row"), card: r(".tp-stack-card"), scroll: r(".tp-stack-scroll"),
  };
};
const before = m;
async function run(){
  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
  const { context, page } = await newRetailPage(browser, "hdr", { viewport:{width:390,height:844}, hasTouch:true, isMobile:true });
  await page.goto(`${BASE_URL}/terminal`, { waitUntil:"domcontentloaded" });
  await page.waitForSelector(".tp-viewport"); await page.waitForTimeout(1400);
  const withRule = await page.evaluate(before);
  // disable the blanket 44px rule and re-measure
  await page.evaluate(() => {
    for (const sheet of document.styleSheets) {
      let rules; try { rules = sheet.cssRules; } catch { continue; }
      for (const rule of rules) {
        if (!rule.media) continue;
        for (const inner of rule.cssRules) {
          if (inner.selectorText && /^button,/.test(inner.selectorText.replace(/\s+/g," "))) {
            inner.style.removeProperty("min-height");
            inner.style.removeProperty("min-width");
          }
        }
      }
    }
  });
  await page.waitForTimeout(600);
  const without = await page.evaluate(before);
  await page.screenshot({ path: "/tmp/claude-1000/-home-runner-workspace/77407836-b974-40ea-96f0-bff2e237e95e/scratchpad/shots4/390-no44rule.png" });
  console.log(JSON.stringify({ withRule, without }, null, 1));
  await context.close(); await browser.close();
}
run().catch(e=>{console.error(e);process.exit(1);});
