import { chromium } from "playwright";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "../scripts/desktop-shots/retail-fixtures.mjs";
const centres = () => {
  const ind = document.querySelector('[data-demo-id="terminal-dock"] div[aria-hidden="true"][style*="width: 65px"]')
    || [...document.querySelectorAll('[data-demo-id="terminal-dock"] div[aria-hidden="true"]')].find(d => d.getBoundingClientRect().width > 50);
  const active = document.querySelector('[data-demo-id="terminal-dock"] [aria-current="page"]');
  const sub = document.querySelector(".tp-subbar-ind");
  const subActive = document.querySelector(".tp-subbar-btn.active");
  const c = (e) => { if (!e) return null; const b = e.getBoundingClientRect(); return +(b.x + b.width/2).toFixed(1); };
  return { dockIndCentre: c(ind), dockActiveCentre: c(active),
           dockDelta: ind && active ? +(c(ind) - c(active)).toFixed(1) : null,
           subIndCentre: c(sub), subActiveCentre: c(subActive),
           subDelta: sub && subActive ? +(c(sub) - c(subActive)).toFixed(1) : null };
};
async function run(){
  const browser = await chromium.launch({ executablePath: CHROMIUM_PATH });
  const { context, page } = await newRetailPage(browser, "rot", { viewport:{width:390,height:844}, hasTouch:true, isMobile:true });
  await page.goto(`${BASE_URL}/terminal`, { waitUntil:"domcontentloaded" });
  await page.waitForSelector(".tp-viewport"); await page.waitForTimeout(1500);
  await page.click('[data-demo-id="retail-add-sale"]'); await page.waitForTimeout(700);
  await page.click('[data-demo-id="retail-mode-split"]'); await page.waitForTimeout(900);
  const before = await page.evaluate(centres);
  await page.setViewportSize({ width: 320, height: 568 });
  await page.waitForTimeout(900);
  const afterShrink = await page.evaluate(centres);
  await page.setViewportSize({ width: 430, height: 932 });
  await page.waitForTimeout(900);
  const afterGrow = await page.evaluate(centres);
  console.log(JSON.stringify({ before, afterShrink, afterGrow }, null, 1));
  await context.close(); await browser.close();
}
run().catch(e=>{console.error(e);process.exit(1);});
EOF
