/* Feature-screen navy panel: where is it clipped, top and bottom? */
import { chromium } from "playwright";
import { mkdir } from "node:fs/promises";
import { BASE_URL, CHROMIUM_PATH, newRetailPage } from "../scripts/desktop-shots/retail-fixtures.mjs";

const OUT = "/tmp/claude-1000/-home-runner-workspace/77407836-b974-40ea-96f0-bff2e237e95e/scratchpad/panels";
const PHONES = [["320x568", 320, 568], ["375x667", 375, 667], ["390x844", 390, 844], ["430x932", 430, 932]];

const panel = () => {
  const vh = window.innerHeight, vw = window.innerWidth;
  const r = (el) => { if (!el) return null; const b = el.getBoundingClientRect();
    return { x: +b.x.toFixed(1), y: +b.y.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1), bottom: +b.bottom.toFixed(1) }; };
  const layer = document.querySelector(".tp-layer:not(.leaving)") || document.querySelector(".tp-layer");
  const screen = layer?.querySelector(".tp-screen");
  const staggers = screen ? [...screen.querySelectorAll(":scope > .stagger")] : [];
  const top = staggers[0], bottom = staggers[1];
  const cs = bottom ? getComputedStyle(bottom) : null;

  // deepest visible content inside the navy panel
  let lowest = null, highest = null;
  if (bottom) {
    for (const el of bottom.querySelectorAll("*")) {
      const b = el.getBoundingClientRect();
      if (b.width === 0 || b.height === 0) continue;
      const s = getComputedStyle(el);
