  const errs = [];
  p.on("pageerror", e => errs.push(String(e)));
  p.on("console", m => { if (m.type() === "error") errs.push(m.text()); });
  await p.goto(F, { waitUntil: "networkidle" });
  await p.waitForTimeout(400);
  // scroll to the goo demo
  await p.locator("#gooDock").scrollIntoViewIfNeeded();
  await p.waitForTimeout(200);
  await p.screenshot({ path: `${OUT}-${scheme}-open.png`, clip: await p.locator(".goo-demo").boundingBox() });
  await p.click("#gooToggle");
  await p.waitForTimeout(200);                       // mid-transition
  await p.screenshot({ path: `${OUT}-${scheme}-mid.png`, clip: await p.locator(".goo-demo").boundingBox() });
  await p.waitForTimeout(600);
  await p.screenshot({ path: `${OUT}-${scheme}-closed.png`, clip: await p.locator(".goo-demo").boundingBox() });
  // phones diagram
  await p.locator("#phones").scrollIntoViewIfNeeded();
  await p.waitForTimeout(150);
  await p.screenshot({ path: `${OUT}-${scheme}-phones.png`, clip: await p.locator("#phones").boundingBox() });
  const overflow = await p.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
  console.log(scheme, "| h-overflow:", overflow, "| errors:", errs.length ? errs : "none");
  await ctx.close();
}
await b.close();
